let quantity = 500;
let plan = 'B';
const costs = () => ({ A: .12 * quantity, B: 20 + .06 * quantity, C: 50 + .03 * quantity });
function update() {
  const values = costs();
  lobeUI.setText('#quantity-value', String(quantity));
  for (const name of ['A', 'B', 'C']) {
    lobeUI.setText('#cost-' + name.toLowerCase(), '$' + values[name].toFixed(2));
    lobeUI.setStyle('#bar-' + name.toLowerCase(), 'width', (values[name] / 120 * 100).toFixed(2) + '%');
  }
  const minimum = Math.min(...Object.values(values));
  const best = Object.keys(values).filter(name => values[name] === minimum);
  lobeUI.setText('#recommendation', best.length > 1 ? 'Plans ' + best.join(' and ') + ' tie at $' + minimum.toFixed(2) + '.' : 'Plan ' + best[0] + ' is cheapest at $' + minimum.toFixed(2) + '.');
}
lobeUI.on('#quantity', 'input', ({ value }) => { quantity = Number(value); update(); });
lobeUI.on('#plan', 'change', ({ value }) => { plan = value; });
lobeUI.on('#continue', 'click', () => { const values = costs(); lobeUI.propose('Use quantity ' + quantity + ' and plan ' + plan + ' at $' + values[plan].toFixed(2) + '. Compare the trade-offs using these illustrative prices: A $' + values.A.toFixed(2) + ', B $' + values.B.toFixed(2) + ', C $' + values.C.toFixed(2) + '.'); });
update();
